public class VariableScopeLifecycleDemo {
    private static int staticCounter = 0; // Class-level scope, heap lifetime
    private final String instanceId;        // Instance-level scope, heap lifetime

    public VariableScopeLifecycleDemo(String instanceId) {
        this.instanceId = instanceId; // 'instanceId' parameter shadows/initializes field
        staticCounter++;
    }

    public void processTransaction(double amount) {
        if (amount > 0.0) {
            double taxRate = 0.08; // Block scope, stack lifetime
            double total = amount + (amount * taxRate);
            System.out.println(instanceId + " Total: " + total);
        }
        // taxRate and total are out of scope here; memory will be popped with stack frame
    }
}
